text:
.button.icon-button.add-reminder-button {
  color: var(--color-primary-default);
  background-image: var(--icon-circle-add-sm);
  margin-inline: 0;
  margin-block-start: calc(3 * var(--space-step));
}

.create-reminder-form {
  display: flex;
  align-items: center;
  gap: calc(3 * var(--space-step));
  margin-block-start: calc(3 * var(--space-step));

  .select {
    flex: 1 auto;
    margin: 0;
  }

  .button {
    margin: 0;
  }

  .delete-button {
    display: flex;
    justify-content: center;
    align-items: center;
    margin-inline-end: var(--button-margin);
  }
}
